/**
 * The shape of the pinned SimulationCraft DoT base-duration artifact, and a
 * runtime validator for it.
 *
 * Generated by `scripts/authority/extract-simc-dot-durations.mjs` from one exact
 * SimulationCraft commit and committed. Nothing here reaches the network.
 *
 * WHAT THIS DATA IS FOR
 *
 * The pinned `core_dot[0]` condition asks `remains<=...`. Warcraft Logs does not
 * report a remaining duration; it reports that a debuff was APPLIED at a time.
 * Turning one into the other needs the DoT's base duration, which is a game fact
 * and so belongs in runtime data with provenance.
 *
 * THE ONE THING IT MUST GET RIGHT: UNITS
 *
 * `_duration` is DBC milliseconds. SimulationCraft expressions are in SECONDS.
 * Those are different numbers for the same fact, and a milliseconds value read
 * as seconds turns an 18-second Garrote into five hours — which would satisfy
 * every `remains<=` threshold in the pinned APL and never once look wrong.
 *
 * So the unit is part of the FIELD NAME everywhere it travels (`baseDurationMs`),
 * the artifact records `durationFieldUnits` explicitly, and the validator
 * rejects an artifact that claims any other unit. The conversion to seconds
 * happens once, in the adapter that produces the binding, and is named there.
 *
 * WHAT IT DELIBERATELY DOES NOT CARRY
 *
 * No haste scaling, no pandemic window, no talent modification, no snapshot.
 * Each of those is a model this project has not built. Storing a base duration
 * and nothing else means a decision needing one of them cannot quietly get a
 * plausible substitute — it gets the base fact, and whoever needs more has to
 * add the model.
 */

/** The artifact schema version this build understands. */
export const SUPPORTED_DOT_DURATION_ARTIFACT_VERSION = 1;

/**
 * The only unit string the artifact may claim.
 *
 * A single-valued union rather than a free string: this is the field that stops
 * a milliseconds/seconds confusion, so it must not be able to say anything else.
 */
export const DOT_DURATION_UNITS = "MILLISECONDS";

export interface DotDurationArtifactSource {
  readonly path: string;
  readonly sha256: string;
  readonly byteLength: number;
}

export interface DotDurationArtifactProvenance {
  readonly repository: string;
  readonly commitSha: string;
  readonly sources: readonly DotDurationArtifactSource[];
  readonly clientDataWowVersion: string;
  readonly clientDataHotfixDate: string;
  readonly clientDataHotfixBuild: number;
  readonly clientDataHotfixHash: string;
  readonly durationFieldName: string;
  /** Always `MILLISECONDS`. Validated, not merely documented. */
  readonly durationFieldUnits: typeof DOT_DURATION_UNITS;
  /** How the durations were established. Machine-extracted, unlike a token binding. */
  readonly dotDataMethod: string;
  readonly extractedOn: string;
  readonly extractorVersion: number;
  /** What the base duration excludes, spelled out. */
  readonly durationSemanticsNote: string;
  /** Why this dataset carries no fight-derived applicability gate. */
  readonly applicabilityNote: string;
}

/** How a token -> spell-id relation was established. */
export type DotBindingMethod = "SPECIALIZATION_SPELL_TABLE";

export interface DotBinding {
  readonly method: DotBindingMethod;
  readonly classId: number;
  readonly specId: number;
  readonly sourcePath: string;
  /** The `create_action` line mapping the APL token to a spell handle. */
  readonly createAction: string;
  /** The `init_spells` line mapping that handle to a named specialization spell. */
  readonly specBinding: string;
  readonly bindingSourcePath: string;
  readonly bindingSourceSha256: string;
}

/**
 * How a DoT's applied duration is computed from its base (M5-D1).
 *
 * TWO MODELS, BECAUSE THE PINNED SOURCE HAS TWO. Garrote's
 * `composite_dot_duration` returns the base unchanged; Rupture's is
 * `data().duration() * ( 1 + rs->get_combo_points() )`. A single stored number
 * would be right for one and wrong for the other at every combo-point count
 * below maximum — and wrong in the direction that understates a remainder, which
 * is what makes a refresh look due when it is not.
 *
 * `COMBO_POINT_SCALED` carries no coefficient: the formula is fixed in C++ and
 * recording a multiplier here would create a second place for it to be wrong.
 * What is recorded is WHERE the formula lives, so the reading can be re-checked.
 */
export type DotDurationModelKind = "FIXED" | "COMBO_POINT_SCALED";

export const DOT_DURATION_MODEL_KINDS = [
  "FIXED",
  "COMBO_POINT_SCALED",
] as const satisfies readonly DotDurationModelKind[];

export interface DotDurationModel {
  readonly kind: DotDurationModelKind;
  /** The pinned file the reading came from. */
  readonly sourcePath: string;
  readonly sourceSha256: string;
  readonly startLine: number;
  readonly endLine: number;
  /** What was read, in words, so the claim can be re-checked rather than trusted. */
  readonly finding: string;
}

/**
 * The periodic-damage effect a tick period was read from (M5-D1).
 *
 * Recorded rather than merely used, because `_amplitude` appears on EVERY effect
 * and only the periodic-damage one means "tick period". Naming the effect index,
 * type and subtype is what lets a reader confirm the right column of the right
 * row was taken.
 */
export interface DotTickPeriodBinding {
  /** `spelleffect_data_t::_index` of the effect the period came from. */
  readonly effectIndex: number;
  /** `_type`. 6 is `E_APPLY_AURA`. */
  readonly effectType: number;
  /** `_subtype`. 3 is `A_PERIODIC_DAMAGE`. */
  readonly effectSubtype: number;
  readonly sourcePath: string;
}

export interface DotDurationIdentity {
  /** The action token as it appears in a SimulationCraft APL line. */
  readonly simcToken: string;
  /** The spell id. This is what a Warcraft Logs aura event carries as `abilityGameID`. */
  readonly abilityGameId: number;
  /** Human-readable only. Never used for matching. */
  readonly displayNameEn: string;
  /** `spell_data_t::_duration`, in MILLISECONDS. Base only. */
  readonly baseDurationMs: number;
  /** `spell_data_t::_cooldown`, in MILLISECONDS. Recorded for traceability. */
  readonly baseCooldownMs: number;
  /**
   * `spelleffect_data_t::_amplitude` of the periodic-damage effect, in
   * MILLISECONDS. The BASE tick period (M5-D1).
   *
   * NOT the tick period at runtime. Haste shortens it, and so does
   * `1 / exsanguinated_rate` (sc_rogue.cpp:2619-2626). Both only ever SHORTEN
   * it, which is precisely what makes this number usable as an UPPER BOUND — and
   * an upper bound on the tick period is what the one-sided `refreshable` proof
   * needs. See `src/specs/rogue/assassination/dot-refreshable.ts`.
   */
  readonly baseTickPeriodMs: number;
  readonly tickPeriodBinding: DotTickPeriodBinding;
  readonly durationModel: DotDurationModel;
  readonly binding: DotBinding;
}

export interface DotDurationArtifact {
  readonly artifactVersion: number;
  readonly datasetId: string;
  readonly artifactRevision: string;
  readonly provenance: DotDurationArtifactProvenance;
  readonly dots: readonly DotDurationIdentity[];
}

/**
 * Field names that must NOT appear on a DoT entry.
 *
 * Each is a value that depends on a specific fight moment, a specific actor or a
 * model this project has not built. Baking one into the dataset would turn a
 * per-decision derivation into a constant — which is precisely how a snapshot or
 * a haste-scaled duration becomes a fact nobody re-checks.
 */
export const FORBIDDEN_DERIVED_DOT_KEYS = [
  "remains",
  "remainsSeconds",
  "baseDurationSeconds",
  "hastedDurationMs",
  "pandemicWindowMs",
  "pmultiplier",
] as const;

export type DotDurationArtifactValidationReason =
  | "NOT_AN_OBJECT"
  | "UNSUPPORTED_ARTIFACT_VERSION"
  | "MALFORMED_PROVENANCE"
  | "UNSUPPORTED_DURATION_UNITS"
  | "MALFORMED_DOTS"
  | "MALFORMED_DOT"
  | "MALFORMED_BINDING"
  | "MALFORMED_DURATION_MODEL"
  | "MALFORMED_TICK_PERIOD"
  | "DUPLICATE_TOKEN"
  | "DUPLICATE_ABILITY_ID";

export type DotDurationArtifactValidation =
  | { readonly ok: true; readonly artifact: DotDurationArtifact }
  | { readonly ok: false; readonly reason: DotDurationArtifactValidationReason; readonly detail: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function str(record: Record<string, unknown>, key: string): string | null {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : null;
}

function positiveInt(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : null;
}

function nonNegativeInt(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : null;
}

function invalid(reason: DotDurationArtifactValidationReason, detail: string): DotDurationArtifactValidation {
  return { ok: false, reason, detail };
}

function validateSources(value: unknown): readonly DotDurationArtifactSource[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;
  const sources: DotDurationArtifactSource[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const path = str(raw, "path");
    const sha256 = str(raw, "sha256");
    const byteLength = positiveInt(raw, "byteLength");
    if (path === null || sha256 === null || byteLength === null) return null;
    if (!/^[0-9a-f]{64}$/.test(sha256)) return null;
    sources.push({ path, sha256, byteLength });
  }
  return sources;
}

function validateProvenance(value: unknown): DotDurationArtifactProvenance | "BAD_UNITS" | null {
  if (!isRecord(value)) return null;
  const repository = str(value, "repository");
  const commitSha = str(value, "commitSha");
  const clientDataWowVersion = str(value, "clientDataWowVersion");
  const clientDataHotfixDate = str(value, "clientDataHotfixDate");
  const clientDataHotfixHash = str(value, "clientDataHotfixHash");
  const durationFieldName = str(value, "durationFieldName");
  const dotDataMethod = str(value, "dotDataMethod");
  const extractedOn = str(value, "extractedOn");
  const durationSemanticsNote = str(value, "durationSemanticsNote");
  const applicabilityNote = str(value, "applicabilityNote");
  const clientDataHotfixBuild = positiveInt(value, "clientDataHotfixBuild");
  const extractorVersion = positiveInt(value, "extractorVersion");
  const sources = validateSources(value["sources"]);

  if (
    repository === null ||
    commitSha === null ||
    clientDataWowVersion === null ||
    clientDataHotfixDate === null ||
    clientDataHotfixHash === null ||
    durationFieldName === null ||
    dotDataMethod === null ||
    extractedOn === null ||
    durationSemanticsNote === null ||
    applicabilityNote === null ||
    clientDataHotfixBuild === null ||
    extractorVersion === null ||
    sources === null
  ) {
    return null;
  }
  if (!/^[0-9a-f]{40}$/.test(commitSha)) return null;

  // Reported distinctly rather than folded into "malformed": an artifact whose
  // units moved is a specific, dangerous failure and deserves to say so.
  if (value["durationFieldUnits"] !== DOT_DURATION_UNITS) return "BAD_UNITS";

  return {
    repository,
    commitSha,
    sources,
    clientDataWowVersion,
    clientDataHotfixDate,
    clientDataHotfixBuild,
    clientDataHotfixHash,
    durationFieldName,
    durationFieldUnits: DOT_DURATION_UNITS,
    dotDataMethod,
    extractedOn,
    extractorVersion,
    durationSemanticsNote,
    applicabilityNote,
  };
}

function validateBinding(value: unknown): DotBinding | null {
  if (!isRecord(value)) return null;
  const method = str(value, "method");
  const sourcePath = str(value, "sourcePath");
  const createAction = str(value, "createAction");
  const specBinding = str(value, "specBinding");
  const bindingSourcePath = str(value, "bindingSourcePath");
  const bindingSourceSha256 = str(value, "bindingSourceSha256");
  const classId = positiveInt(value, "classId");
  const specId = positiveInt(value, "specId");

  if (
    method !== "SPECIALIZATION_SPELL_TABLE" ||
    sourcePath === null ||
    createAction === null ||
    specBinding === null ||
    bindingSourcePath === null ||
    bindingSourceSha256 === null ||
    classId === null ||
    specId === null
  ) {
    return null;
  }
  if (!/^[0-9a-f]{64}$/.test(bindingSourceSha256)) return null;

  return {
    method,
    classId,
    specId,
    sourcePath,
    createAction,
    specBinding,
    bindingSourcePath,
    bindingSourceSha256,
  };
}

function validateDurationModel(value: unknown): DotDurationModel | null {
  if (!isRecord(value)) return null;
  const kind = str(value, "kind");
  const sourcePath = str(value, "sourcePath");
  const sourceSha256 = str(value, "sourceSha256");
  const finding = str(value, "finding");
  const startLine = positiveInt(value, "startLine");
  const endLine = positiveInt(value, "endLine");
  if (
    kind === null ||
    !(DOT_DURATION_MODEL_KINDS as readonly string[]).includes(kind) ||
    sourcePath === null ||
    sourceSha256 === null ||
    finding === null ||
    startLine === null ||
    endLine === null
  ) {
    return null;
  }
  if (!/^[0-9a-f]{64}$/.test(sourceSha256)) return null;
  if (endLine < startLine) return null;
  return { kind: kind as DotDurationModelKind, sourcePath, sourceSha256, startLine, endLine, finding };
}

function validateTickPeriodBinding(value: unknown): DotTickPeriodBinding | null {
  if (!isRecord(value)) return null;
  const sourcePath = str(value, "sourcePath");
  const effectIndex = nonNegativeInt(value, "effectIndex");
  const effectType = nonNegativeInt(value, "effectType");
  const effectSubtype = nonNegativeInt(value, "effectSubtype");
  if (sourcePath === null || effectIndex === null || effectType === null || effectSubtype === null) {
    return null;
  }
  return { effectIndex, effectType, effectSubtype, sourcePath };
}

export function validateDotDurationArtifact(value: unknown): DotDurationArtifactValidation {
  if (!isRecord(value)) return invalid("NOT_AN_OBJECT", "artifact root is not an object");

  const artifactVersion = value["artifactVersion"];
  if (artifactVersion !== SUPPORTED_DOT_DURATION_ARTIFACT_VERSION) {
    return invalid(
      "UNSUPPORTED_ARTIFACT_VERSION",
      `artifactVersion ${String(artifactVersion)} is not ${SUPPORTED_DOT_DURATION_ARTIFACT_VERSION}`,
    );
  }

  const datasetId = str(value, "datasetId");
  const artifactRevision = str(value, "artifactRevision");
  if (datasetId === null || artifactRevision === null) {
    return invalid("NOT_AN_OBJECT", "artifact header fields are missing or malformed");
  }

  const provenance = validateProvenance(value["provenance"]);
  if (provenance === "BAD_UNITS") {
    return invalid(
      "UNSUPPORTED_DURATION_UNITS",
      `provenance.durationFieldUnits must be '${DOT_DURATION_UNITS}'; a duration whose unit is unconfirmed cannot be converted`,
    );
  }
  if (provenance === null) {
    return invalid("MALFORMED_PROVENANCE", "provenance is incomplete or a hash is not a hash");
  }

  const dotsRaw = value["dots"];
  if (!Array.isArray(dotsRaw) || dotsRaw.length === 0) {
    return invalid("MALFORMED_DOTS", "dots is not a non-empty array");
  }

  const dots: DotDurationIdentity[] = [];
  const seenTokens = new Set<string>();
  const seenIds = new Set<number>();

  for (let index = 0; index < dotsRaw.length; index += 1) {
    const raw = dotsRaw[index];
    if (!isRecord(raw)) return invalid("MALFORMED_DOT", `dots[${index}] is not an object`);
    for (const forbidden of FORBIDDEN_DERIVED_DOT_KEYS) {
      if (forbidden in raw) {
        return invalid(
          "MALFORMED_DOT",
          `dots[${index}] stores '${forbidden}'; that is derived per decision, never baked into the dataset`,
        );
      }
    }

    const simcToken = str(raw, "simcToken");
    const nameEn = str(raw, "displayNameEn");
    const abilityGameId = positiveInt(raw, "abilityGameId");
    const baseDurationMs = positiveInt(raw, "baseDurationMs");
    const baseCooldownMs = nonNegativeInt(raw, "baseCooldownMs");
    const binding = validateBinding(raw["binding"]);

    if (
      simcToken === null ||
      nameEn === null ||
      abilityGameId === null ||
      baseDurationMs === null ||
      baseCooldownMs === null
    ) {
      // A non-positive duration lands here too, and that is intended: `-1` is the
      // DBC sentinel for a permanent aura, and a permanent aura cannot anchor a
      // remaining-duration derivation. Refusing it is the fail-closed answer.
      return invalid(
        "MALFORMED_DOT",
        `dots[${index}] is missing required fields or has a non-positive duration`,
      );
    }
    if (binding === null) {
      return invalid("MALFORMED_BINDING", `dots[${index}] has an unusable binding record`);
    }

    const durationModel = validateDurationModel(raw["durationModel"]);
    if (durationModel === null) {
      return invalid(
        "MALFORMED_DURATION_MODEL",
        `dots[${index}] has no usable durationModel; a DoT whose scaling is unstated cannot be derived`,
      );
    }

    // A POSITIVE tick period. Zero would mean "no periodic effect", which cannot
    // be a DoT, and it would make the `refreshable` bound `remains > 0` — true
    // for every live DoT, which would prove `refreshable` FALSE always.
    const baseTickPeriodMs = positiveInt(raw, "baseTickPeriodMs");
    const tickPeriodBinding = validateTickPeriodBinding(raw["tickPeriodBinding"]);
    if (baseTickPeriodMs === null || tickPeriodBinding === null) {
      return invalid(
        "MALFORMED_TICK_PERIOD",
        `dots[${index}] has no positive baseTickPeriodMs with a binding naming the effect it came from`,
      );
    }

    if (seenTokens.has(simcToken)) return invalid("DUPLICATE_TOKEN", simcToken);
    if (seenIds.has(abilityGameId)) return invalid("DUPLICATE_ABILITY_ID", String(abilityGameId));
    seenTokens.add(simcToken);
    seenIds.add(abilityGameId);

    dots.push({
      simcToken,
      abilityGameId,
      displayNameEn: nameEn,
      baseDurationMs,
      baseCooldownMs,
      baseTickPeriodMs,
      tickPeriodBinding,
      durationModel,
      binding,
    });
  }

  return { ok: true, artifact: { artifactVersion, datasetId, artifactRevision, provenance, dots } };
}
